import base64
import sys

# Import your desired parser here. 
# For example, to test HDFC Bank:
from services.importers.bank_pdf_importers import HdfcBankPDFImporter

def test_base64_string(base64_string: str, password: str = None):
    print("Decoding base64 string...")
    
    try:
        # The Gmail API returns URL-safe base64, so we decode it here
        pdf_bytes = base64.urlsafe_b64decode(base64_string)
        print(f"Decoded {len(pdf_bytes)} bytes. Attempting to parse...\n")
    except Exception as e:
        print(f"Failed to decode Base64 string: {e}")
        sys.exit(1)

    # ---------------------------------------------------------
    # Change the Importer class below to whichever one you 
    # are trying to test (e.g. ChaseCreditCardPDFImporter)
    # ---------------------------------------------------------
    importer = HdfcBankPDFImporter()
    
    try:
        result = importer.parse(
            file_content=pdf_bytes, 
            filename="base64_test_statement.pdf", 
            password=str(password) if password else None
        )
        
        print("======== IMPORT RESULTS ========")
        print(f"Total Transactions Parsed: {len(result.transactions)}")
        
        # Print the first few transactions to see if they look right!
        if result.transactions:
            print("\nFirst 3 Transactions:")
            for tx in result.transactions[:3]:
                print(f" [{tx.date}] {tx.description} : {tx.amount} ({tx.type})")
                
        if result.errors:
            print(f"\nThere were {len(result.errors)} errors encountered:")
            for err in result.errors:
                print(f" - {err}")
                
    except Exception as e:
        print(f"A fatal error occurred during parsing: {e}")


